"""The kitty itself: members, expenses, payments, rates, and the sums.

Money in the main currency is handled internally as whole cents (ints) so
that balances always add up exactly. An expense's own amount, which may be
in another currency, is kept as a Decimal.
"""

import csv
import datetime
import json
import os
import re
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from fractions import Fraction

FILE_NAME = "kitty.json"
DEFAULT_CATEGORY = "other"


class KittyError(Exception):
    """A problem the user can fix, reported as a message rather than a crash."""


# ---------------------------------------------------------------- parsing


def parse_amount(text, what="amount"):
    """Parse a positive amount of money with at most two decimals."""
    try:
        value = Decimal(text.strip())
    except (InvalidOperation, AttributeError):
        raise KittyError("%s must be a number, got %r" % (what, text))
    if not value.is_finite():
        raise KittyError("%s must be a number, got %r" % (what, text))
    if value <= 0:
        raise KittyError("%s must be more than zero, got %r" % (what, text))
    if value != value.quantize(Decimal("0.01")):
        raise KittyError("%s can have at most two decimals, got %r" % (what, text))
    return value


def parse_positive(text, what):
    """Parse a positive number of any precision (rates, shares, percents)."""
    try:
        value = Decimal(text.strip())
    except (InvalidOperation, AttributeError):
        raise KittyError("%s must be a number, got %r" % (what, text))
    if not value.is_finite():
        raise KittyError("%s must be a number, got %r" % (what, text))
    if value <= 0:
        raise KittyError("%s must be more than zero, got %r" % (what, text))
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", code):
        raise KittyError("currency must be a three-letter code like EUR or USD, got %r" % text)
    return code


def parse_date(text):
    try:
        return datetime.datetime.strptime(text.strip(), "%Y-%m-%d").date().isoformat()
    except ValueError:
        raise KittyError("date must look like 2026-07-14, got %r" % text)


def parse_name(text):
    name = text.strip()
    if not name:
        raise KittyError("name can't be empty")
    if "," in name or "=" in name:
        raise KittyError("name can't contain ',' or '=', got %r" % text)
    return name


def parse_pairs(text, option):
    """Parse 'A=30,B=20' into [('A', '30'), ('B', '20')]."""
    pairs = []
    for part in text.split(","):
        name, sep, value = part.partition("=")
        if not sep or not name.strip() or not value.strip():
            raise KittyError("%s should look like A=30,B=20, got %r" % (option, text))
        pairs.append((name.strip(), value.strip()))
    return pairs


def parse_names(text, option):
    names = [part.strip() for part in text.split(",")]
    if not all(names):
        raise KittyError("%s should look like A,B, got %r" % (option, text))
    return names


# ---------------------------------------------------------------- money


def to_cents(value):
    """Round a Decimal amount to whole cents."""
    return int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def fmt_cents(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return "%s%d.%02d" % (sign, cents // 100, cents % 100)


def cents_of(text):
    return to_cents(Decimal(text))


def fmt_amount(value):
    return str(Decimal(value).quantize(Decimal("0.01")))


def allocate(total, weights):
    """Split `total` cents in proportion to `weights`, so the parts add up exactly.

    Each part is rounded down, then the leftover cents go to the parts that
    lost the most to rounding (earlier names first on ties).
    """
    weights = [Fraction(w) for w in weights]
    weight_sum = sum(weights)
    exact = [Fraction(total) * w / weight_sum for w in weights]
    parts = [int(x // 1) for x in exact]
    leftover = total - sum(parts)
    by_remainder = sorted(range(len(exact)), key=lambda i: (-(exact[i] - parts[i]), i))
    for i in by_remainder[:leftover]:
        parts[i] += 1
    return parts


# ---------------------------------------------------------------- the kitty


class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    # ----- loading and saving

    @classmethod
    def create(cls, folder, currency):
        path = os.path.join(folder, FILE_NAME)
        if os.path.exists(path):
            raise KittyError("there is already a kitty here (%s); not overwriting it" % FILE_NAME)
        data = {
            "currency": parse_currency(currency),
            "members": [],
            "rates": {},
            "expenses": [],
            "payments": [],
            "next_expense_id": 1,
            "next_payment_id": 1,
            "next_seq": 1,
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, folder):
        path = os.path.join(folder, FILE_NAME)
        if not os.path.exists(path):
            raise KittyError("no kitty here yet; start one with: python3 -m kitty init EUR")
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            raise KittyError("couldn't read %s: %s" % (FILE_NAME, e))
        required = ("currency", "members", "rates", "expenses", "payments",
                    "next_expense_id", "next_payment_id", "next_seq")
        if not isinstance(data, dict) or any(key not in data for key in required):
            raise KittyError("%s doesn't look like a kitty file" % FILE_NAME)
        return cls(data, path)

    def save(self):
        """Write the file atomically so a crash can't leave it half-written."""
        folder = os.path.dirname(os.path.abspath(self.path))
        fd, tmp = tempfile.mkstemp(dir=folder, prefix=".kitty-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    # ----- helpers

    @property
    def currency(self):
        return self.data["currency"]

    @property
    def members(self):
        return self.data["members"]

    def _member(self, text):
        name = text.strip()
        if name not in self.members:
            known = ", ".join(self.members) if self.members else "nobody yet"
            raise KittyError("%r isn't in the group (members: %s)" % (name, known))
        return name

    def _rate(self, currency):
        if currency == self.currency:
            return Decimal(1)
        if currency not in self.data["rates"]:
            raise KittyError("no exchange rate for %s yet; set one with: rate set %s <value>"
                             % (currency, currency))
        return Decimal(self.data["rates"][currency])

    def _next(self, key):
        value = self.data[key]
        self.data[key] = value + 1
        return value

    # ----- members

    def add_member(self, text):
        name = parse_name(text)
        if name in self.members:
            raise KittyError("%r is already in the group" % name)
        self.members.append(name)
        return name

    def remove_member(self, text):
        name = self._member(text)
        if any(entry for entry in self._timeline() if name in self._changes(entry)):
            raise KittyError("%s is part of expenses or payments already; remove those first"
                             % name)
        self.members.remove(name)
        return name

    # ----- rates

    def set_rate(self, currency, value):
        code = parse_currency(currency)
        if code == self.currency:
            raise KittyError("%s is the main currency; its rate is always 1" % code)
        rate = parse_positive(value, "rate")
        self.data["rates"][code] = str(rate)
        return code, rate

    # ----- expenses

    def add_expense(self, payer, amount, description, among=None, exact=None, shares=None,
                    percent=None, currency=None, date=None, category=None):
        payer = self._member(payer)
        amount = parse_amount(amount)
        description = description.strip()
        if not description:
            raise KittyError("description can't be empty")
        currency = parse_currency(currency) if currency else self.currency
        rate = self._rate(currency)
        base = to_cents(amount * rate)
        date = parse_date(date) if date else datetime.date.today().isoformat()
        category = (category or DEFAULT_CATEGORY).strip()
        if not category:
            raise KittyError("category can't be empty")

        chosen = [opt for opt, val in (("--among", among), ("--exact", exact),
                                       ("--shares", shares), ("--percent", percent))
                  if val is not None]
        if len(chosen) > 1:
            raise KittyError("use only one of %s" % ", ".join(chosen))

        if among is not None:
            names = [self._member(n) for n in parse_names(among, "--among")]
            weights = [1] * len(names)
        elif exact is not None:
            pairs = parse_pairs(exact, "--exact")
            names = [self._member(n) for n, _ in pairs]
            weights = [parse_amount(v, "amount for %s" % n) for n, v in pairs]
            if sum(weights) != amount:
                raise KittyError("--exact amounts add up to %s but the expense is %s"
                                 % (fmt_amount(sum(weights)), fmt_amount(amount)))
        elif shares is not None:
            pairs = parse_pairs(shares, "--shares")
            names = [self._member(n) for n, _ in pairs]
            weights = [parse_positive(v, "shares for %s" % n) for n, v in pairs]
        elif percent is not None:
            pairs = parse_pairs(percent, "--percent")
            names = [self._member(n) for n, _ in pairs]
            weights = [parse_positive(v, "percent for %s" % n) for n, v in pairs]
            if sum(weights) != 100:
                raise KittyError("--percent values add up to %s, not 100" % sum(weights))
        else:
            names = list(self.members)
            weights = [1] * len(names)

        duplicates = sorted({n for n in names if names.count(n) > 1})
        if duplicates:
            raise KittyError("%s listed more than once" % ", ".join(duplicates))

        parts = allocate(base, weights)
        expense = {
            "id": self._next("next_expense_id"),
            "seq": self._next("next_seq"),
            "date": date,
            "payer": payer,
            "description": description,
            "amount": fmt_amount(amount),
            "currency": currency,
            "rate": str(rate),
            "base_amount": fmt_cents(base),
            "category": category,
            "shares": {name: fmt_cents(part) for name, part in zip(names, parts)},
        }
        self.data["expenses"].append(expense)
        return expense

    def remove_expense(self, text):
        expense_id = self._parse_id(text, "expense")
        for expense in self.data["expenses"]:
            if expense["id"] == expense_id:
                self.data["expenses"].remove(expense)
                return expense
        raise KittyError("there's no expense with ID %d" % expense_id)

    def list_expenses(self):
        keys = ("id", "date", "payer", "description", "amount", "currency", "base_amount",
                "category", "shares")
        return [{key: expense[key] for key in keys} for expense in self.data["expenses"]]

    # ----- payments

    def add_payment(self, sender, receiver, amount, currency=None, date=None):
        sender = self._member(sender)
        receiver = self._member(receiver)
        if sender == receiver:
            raise KittyError("someone can't pay themselves back")
        amount = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.currency
        rate = self._rate(currency)
        date = parse_date(date) if date else datetime.date.today().isoformat()
        payment = {
            "id": self._next("next_payment_id"),
            "seq": self._next("next_seq"),
            "date": date,
            "from": sender,
            "to": receiver,
            "amount": fmt_amount(amount),
            "currency": currency,
            "rate": str(rate),
            "base_amount": fmt_cents(to_cents(amount * rate)),
        }
        self.data["payments"].append(payment)
        return payment

    def remove_payment(self, text):
        payment_id = self._parse_id(text, "payment")
        for payment in self.data["payments"]:
            if payment["id"] == payment_id:
                self.data["payments"].remove(payment)
                return payment
        raise KittyError("there's no payment with ID %d" % payment_id)

    def list_payments(self):
        keys = ("id", "date", "from", "to", "amount", "currency", "base_amount")
        return [{key: payment[key] for key in keys} for payment in self.data["payments"]]

    @staticmethod
    def _parse_id(text, what):
        try:
            return int(text)
        except ValueError:
            raise KittyError("%s ID must be a whole number, got %r" % (what, text))

    # ----- the sums

    def _timeline(self):
        """Expenses and payments together, by date and then by when they were added."""
        entries = self.data["expenses"] + self.data["payments"]
        return sorted(entries, key=lambda e: (e["date"], e["seq"]))

    @staticmethod
    def _changes(entry):
        """How much each person's balance moves because of one expense or payment."""
        changes = {}
        if "payer" in entry:
            changes[entry["payer"]] = cents_of(entry["base_amount"])
            for name, share in entry["shares"].items():
                changes[name] = changes.get(name, 0) - cents_of(share)
        else:
            amount = cents_of(entry["base_amount"])
            changes[entry["from"]] = amount
            changes[entry["to"]] = -amount
        return changes

    def balances(self):
        totals = {name: 0 for name in self.members}
        for entry in self._timeline():
            for name, change in self._changes(entry).items():
                totals[name] = totals.get(name, 0) + change
        return totals

    def settle(self):
        """Suggest transfers: the biggest debtor pays the biggest creditor, repeatedly."""
        order = {name: i for i, name in enumerate(self.members)}
        balances = self.balances()
        owed = [[c, n] for n, c in balances.items() if c > 0]
        owing = [[-c, n] for n, c in balances.items() if c < 0]
        transfers = []
        while owed and owing:
            owed.sort(key=lambda x: (-x[0], order.get(x[1], 0)))
            owing.sort(key=lambda x: (-x[0], order.get(x[1], 0)))
            amount = min(owed[0][0], owing[0][0])
            transfers.append({"from": owing[0][1], "to": owed[0][1], "amount": amount})
            owed[0][0] -= amount
            owing[0][0] -= amount
            owed = [x for x in owed if x[0]]
            owing = [x for x in owing if x[0]]
        return transfers

    def history(self, text):
        name = self._member(text)
        rows = []
        balance = 0
        for entry in self._timeline():
            changes = self._changes(entry)
            if name not in changes:
                continue
            balance += changes[name]
            if "payer" in entry:
                description = entry["description"]
            elif entry["from"] == name:
                description = "Payment to %s" % entry["to"]
            else:
                description = "Payment from %s" % entry["from"]
            rows.append({"date": entry["date"], "description": description,
                         "change": changes[name], "balance": balance})
        return rows

    def report(self):
        """Per category, what each person's shares of the expenses add up to."""
        order = {name: i for i, name in enumerate(self.members)}
        totals = {}
        for expense in self.data["expenses"]:
            category = totals.setdefault(expense["category"], {})
            for name, share in expense["shares"].items():
                category[name] = category.get(name, 0) + cents_of(share)
        return {
            category: dict(sorted(people.items(), key=lambda p: order.get(p[0], len(order))))
            for category, people in sorted(totals.items())
        }

    def export_csv(self, path):
        columns = ["id", "date", "payer", "description", "amount", "currency", "category",
                   "base_amount"]
        expenses = sorted(self.data["expenses"], key=lambda e: e["id"])
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(columns)
                for expense in expenses:
                    writer.writerow([expense[c] for c in columns])
        except OSError as e:
            raise KittyError("couldn't write %s: %s" % (path, e.strerror or e))
        return len(expenses)
"""Command line: python3 -m kitty <command> ...

Reports go to standard output as JSON. Short confirmations and error
messages go to standard error, so scripts reading the output only see JSON.
"""

import argparse
import json
import os
import sys

from kitty.core import Kitty, KittyError, fmt_cents


class Parser(argparse.ArgumentParser):
    """Report usage mistakes like any other error: a message and exit status 1."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, "%s: error: %s\n" % (self.prog, message))


def build_parser():
    parser = Parser(prog="python3 -m kitty",
                    description="Keep track of shared trip costs and who owes whom.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND")
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty in this folder")
    p.add_argument("currency", help="main currency, e.g. EUR")

    member = commands.add_parser("member", help="add, remove or list people")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION")
    member_cmds.required = True
    member_cmds.add_parser("add", help="add someone").add_argument("name")
    member_cmds.add_parser("remove", help="remove someone").add_argument("name")
    member_cmds.add_parser("list", help="list everyone")

    expense = commands.add_parser("expense", help="add, remove or list expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION")
    expense_cmds.required = True
    p = expense_cmds.add_parser("add", help="record something someone paid for")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B", help="split equally between only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="when (default: today)")
    p.add_argument("--category", help="e.g. food (default: other)")
    expense_cmds.add_parser("list", help="list all expenses")
    expense_cmds.add_parser("remove", help="remove an expense").add_argument("id")

    payment = commands.add_parser("payment", help="record someone paying someone back")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION")
    payment_cmds.required = True
    p = payment_cmds.add_parser("add", help="record a payment")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("receiver", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="when (default: today)")
    payment_cmds.add_parser("list", help="list all payments")
    payment_cmds.add_parser("remove", help="remove a payment").add_argument("id")

    rate = commands.add_parser("rate", help="set exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION")
    rate_cmds.required = True
    p = rate_cmds.add_parser("set", help="one unit of CURRENCY is worth VALUE main currency")
    p.add_argument("currency")
    p.add_argument("value")
    rate_cmds.add_parser("list", help="list exchange rates")

    commands.add_parser("balances", help="how far up or down each person is")
    commands.add_parser("settle", help="suggest who should pay whom")
    commands.add_parser("history", help="everything that affected one person").add_argument("name")
    commands.add_parser("report", help="each person's share of spending per category")
    commands.add_parser("export", help="save expenses to a CSV file").add_argument("file")
    return parser


def say(message):
    print(message, file=sys.stderr)


def show(value):
    print(json.dumps(value, ensure_ascii=False))


def run(args, folder):
    if args.command == "init":
        kitty = Kitty.create(folder, args.currency)
        say("Started a new kitty in %s." % kitty.currency)
        return

    kitty = Kitty.load(folder)
    command = (args.command, getattr(args, "action", None))

    if command == ("member", "add"):
        say("Added %s." % kitty.add_member(args.name))
    elif command == ("member", "remove"):
        say("Removed %s." % kitty.remove_member(args.name))
    elif command == ("member", "list"):
        show(kitty.members)
    elif command == ("expense", "add"):
        expense = kitty.add_expense(
            args.payer, args.amount, " ".join(args.description), among=args.among,
            exact=args.exact, shares=args.shares, percent=args.percent,
            currency=args.currency, date=args.date, category=args.category)
        print(expense["id"])
    elif command == ("expense", "list"):
        show(kitty.list_expenses())
    elif command == ("expense", "remove"):
        expense = kitty.remove_expense(args.id)
        say("Removed expense %d (%s)." % (expense["id"], expense["description"]))
    elif command == ("payment", "add"):
        print(kitty.add_payment(args.sender, args.receiver, args.amount,
                                currency=args.currency, date=args.date)["id"])
    elif command == ("payment", "list"):
        show(kitty.list_payments())
    elif command == ("payment", "remove"):
        payment = kitty.remove_payment(args.id)
        say("Removed payment %d (%s to %s)." % (payment["id"], payment["from"], payment["to"]))
    elif command == ("rate", "set"):
        code, rate = kitty.set_rate(args.currency, args.value)
        say("1 %s = %s %s (used for expenses and payments added from now on)."
            % (code, rate, kitty.currency))
    elif command == ("rate", "list"):
        show(kitty.data["rates"])
    elif args.command == "balances":
        show({name: fmt_cents(c) for name, c in kitty.balances().items()})
    elif args.command == "settle":
        show([dict(t, amount=fmt_cents(t["amount"])) for t in kitty.settle()])
    elif args.command == "history":
        show([dict(row, change=fmt_cents(row["change"]), balance=fmt_cents(row["balance"]))
              for row in kitty.history(args.name)])
    elif args.command == "report":
        show({category: {name: fmt_cents(c) for name, c in people.items()}
              for category, people in kitty.report().items()})
    elif args.command == "export":
        count = kitty.export_csv(args.file)
        say("Saved %d expense%s to %s." % (count, "" if count == 1 else "s", args.file))

    if command[1] in ("add", "remove", "set"):
        kitty.save()


def main(argv=None, folder=None):
    args = build_parser().parse_args(argv)
    try:
        run(args, folder or os.getcwd())
    except KittyError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1
    return 0
